  "tips": [
   "Flavor-Pairing-Logik: Blumenkohl teilt Sulphur- und Citrus-Aromen mit Tomate/Käse; das Rösten im Ofen erzeugt zusätzliche Maillard-Röstaromen, die laut Flavour Matrix Blumenkohl besonders gut mit Cocoa/Käse/Curry harmonieren lassen. Der braune Zucker balanciert die Säure der Tomaten (Süß↔Sauer).",
   "Auflaufform ist mit 28 cm angegeben, unsere große Form hat 30×20 cm – passt problemlos, ggf. Sauce etwas breiter verteilen.",
   "Max. Ofentemperatur für die Glas-Auflaufform liegt bei 220–240 °C – die 210 °C hier sind also unproblematisch.",
   "Dazu passt frisches Baguette, falls gewünscht.",
   "Vegane Variante: Käse weglassen, stattdessen Brösel mit gehackten Mandeln/Cashews vermengen."
  ],
